195	    /**
196	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
197	     * source of truth for how an email is persisted, so inputs that differ only in letter case
198	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
199	     * (create and update, mapper or hand-copied) stores the same canonical value.
200	     *
201	     * @param email the raw email, possibly {@code null}
202	     * @return the lower-cased form, or {@code null} if the input was {@code null}
203	     */
204	    public static String normalizeEmail(String email) {
205	        return email == null ? null : email.toLowerCase();
206	    }
207	
208	    /**
209	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
210	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
211	     */
212	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
213	        "mailinator.com",
214	        "tempmail.com",
215	        "guerrillamail.com");
216	
217	    /**
218	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
219	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
220	     * This is the single source of truth for which email domains are rejected, shared by any
221	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
222	     *
223	     * @param email the owner's email, possibly {@code null}
224	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
225	     */
226	    public static boolean isDisposableEmailDomain(String email) {
227	        if (email == null) {
228	            return false;
229	        }
230	        int at = email.lastIndexOf('@');
231	        if (at < 0) {
232	            return false;
233	        }
234	        String domain = email.substring(at + 1).toLowerCase();
235	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
236	    }
237	
238	    /**
239	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
240	     * truth for how a telephone is compared and persisted, so inputs that differ only in
241	     * formatting (spaces, dashes, brackets) are treated as the same number.
242	     *
243	     * <p>The rules are:
244	     * <ul>
245	     *   <li>spaces, dashes and brackets are stripped;</li>
246	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
247	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
248	     *       is dropped from the national digits;</li>
249	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
250	     *   <li>for a recognized country code the national number (the digits after the country
251	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
252	     *       digits and {@code '+1'} requires 10.</li>
253	     * </ul>
254	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
255	     * values are returned unchanged.
256	     *
257	     * @param telephone the raw telephone, possibly {@code null}
258	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
259	     *     valid E.164 number
260	     */
261	    public static String normalizeTelephone(String telephone) {
262	        if (telephone == null) {
263	            return null;
264	        }
265	        String trimmed = telephone.trim();
266	        boolean hasCountryCode = trimmed.startsWith("+");
267	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
268	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
269	        if (hasCountryCode) {
270	            stripped = stripped.substring(1);
271	        }
272	        if (!stripped.matches("\\d+")) {
273	            return null;
274	        }
275	        String digits;
276	        if (hasCountryCode) {
277	            digits = stripped;
278	        } else {
279	            if (stripped.startsWith("0")) {
280	                stripped = stripped.substring(1);
281	            }
282	            digits = "61" + stripped;
283	        }
284	        if (digits.length() < 8 || digits.length() > 15) {
285	            return null;
286	        }
287	        if (!hasValidNationalNumberLength(digits)) {
288	            return null;
289	        }
290	        return "+" + digits;
291	    }
292	
293	    /**
294	     * Format a stored E.164 telephone for human display: the country code, a space, then the
295	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
296	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
297	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
298	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
299	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
300	     * kept unchanged elsewhere.
301	     *
302	     * @param telephone the stored E.164 telephone, possibly {@code null}
303	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
304	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
305	     *     unchanged
306	     */
307	    public static String telephoneDisplay(String telephone) {
308	        if (telephone == null) {
309	            return null;
310	        }
311	        if (!telephone.matches("\\+\\d+")) {
312	            return telephone;
313	        }
314	        String digits = telephone.substring(1);
315	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
316	            if (digits.startsWith(countryCode)) {
317	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
318	            }
319	        }
320	        return "+" + groupDigits(digits);
321	    }
322	
323	    /**
324	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
325	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
326	     * {@code "412345678"} becomes {@code "412 345 678"}).
327	     *
328	     * @param digits the national digits
329	     * @return the space-grouped digits
330	     */
331	    private static String groupDigits(String digits) {
332	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
333	        for (int i = 0; i < digits.length(); i++) {
334	            if (i > 0 && i % 3 == 0) {
335	                grouped.append(' ');
336	            }
337	            grouped.append(digits.charAt(i));
338	        }
339	        return grouped.toString();
340	    }
341	
342	    /**
343	     * Required national-number length (the count of digits after the country code) for each
344	     * recognized country code, longest country code first so the prefix match is unambiguous.
345	     */
346	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
347	    static {
348	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
349	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
350	    }
351	
352	    /**
353	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
354	     * length its country code requires. A country code with no registered length places no
355	     * additional constraint and is accepted.
356	     *
357	     * @param digits the E.164 digits without the leading {@code '+'}
358	     * @return {@code true} if the national-number length is valid for the country code
359	     */
360	    private static boolean hasValidNationalNumberLength(String digits) {
361	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
362	            String countryCode = entry.getKey();
363	            if (digits.startsWith(countryCode)) {
364	                return digits.length() - countryCode.length() == entry.getValue();
365	            }
366	        }
367	        return true;
368	    }
