703	    /**
704	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
705	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
706	     * value is deterministic in the customer code and is the standard Luhn check digit: each
707	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
708	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
709	     * brings the weighted sum up to the next multiple of ten.
710	     *
711	     * @param customerCode the owner's customer code, possibly {@code null}
712	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
713	     */
714	    public static Integer checkDigit(String customerCode) {
715	        if (customerCode == null) {
716	            return null;
717	        }
718	        int sum = 0;
719	        boolean dbl = true;
720	        for (int i = customerCode.length() - 1; i >= 0; i--) {
721	            char c = customerCode.charAt(i);
722	            if (c < '0' || c > '9') {
723	                continue;
724	            }
725	            int d = c - '0';
726	            if (dbl) {
727	                d *= 2;
728	                if (d > 9) {
729	                    d -= 9;
730	                }
731	            }
732	            sum += d;
733	            dbl = !dbl;
734	        }
735	        return (10 - (sum % 10)) % 10;
736	    }
