750	    /**
751	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
752	     * date. The age in whole years is the number of completed years between {@code birthDate} and
753	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
754	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
755	     * two fields and is only defined when both are present.
756	     *
757	     * @param birthDate the owner's date of birth, possibly {@code null}
758	     * @param registrationDate the owner's registration date, possibly {@code null}
759	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
760	     *     is {@code null}
761	     */
762	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
763	        if (birthDate == null || registrationDate == null) {
764	            return null;
765	        }
766	        int age = Period.between(birthDate, registrationDate).getYears();
767	        if (age < 18) {
768	            return "MINOR";
769	        }
770	        if (age < 65) {
771	            return "ADULT";
772	        }
773	        return "SENIOR";
774	    }
